import Foundation
import PowerAuth2
import WultraPowerAuthNetworking

class TestUtils {
    
    struct FakeData: Codable { }
    
    enum FakeEndpoint {
        typealias EndpointType = WPNEndpointBasic<WPNRequestBase, WPNResponse<FakeData>>
        static let endpoint: EndpointType = .init(endpointURLPath: "/fake/path")
    }
    
    static func createDummyService(url: String = "https://fake.url/") throws -> WPNNetworkingService {
        WPNLogger.verboseLevel = .debug
        let pa = try PowerAuthSDK(
            configuration: .init(
                instanceId: "test",
                baseEndpointUrl: url,
                configuration: .dummySDKConfig
            )
        )
        return WPNNetworkingService(
            powerAuth: pa,
            config: .init(
                baseUrl: URL(string: url)!),
            serviceName: "dummy"
        )
    }
}

private extension String {
    /// Dummy PowerAuth SDK Config
    static let dummySDKConfig = """

"""
}
